// Package botsource provides the checkout's build inputs for preparing a Linux
// assistant runtime through Docker on other operating systems.
package botsource

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"embed"
	"fmt"
	"io"
	"io/fs"
	"regexp"
	"strings"
)

//go:embed assets/*
var embedded embed.FS

const archivePath = "assets/term-llm-source.tar.gz"

var goVersionPattern = regexp.MustCompile(`^[1-9][0-9]*\.[0-9]+(?:\.[0-9]+)?$`)

// Source returns a deterministic tar.gz of this checkout and the Go version
// pinned by its root go.mod. It is generated by make build before compilation.
func Source() (archive []byte, goVersion string, err error) {
	return source(embedded)
}

func source(files fs.FS) ([]byte, string, error) {
	archive, err := fs.ReadFile(files, archivePath)
	if err == nil {
		var version string
		version, err = archiveGoVersion(archive)
		if err == nil {
			return archive, version, nil
		}
	}
	return nil, "", fmt.Errorf("assistant build source is unavailable; rebuild term-llm with make build: %w", err)
}

// archiveGoVersion inspects go.mod in place; it never extracts archive paths to
// disk. Bound decompression and the module file before parsing a Docker tag.
func archiveGoVersion(archive []byte) (string, error) {
	zr, err := gzip.NewReader(bytes.NewReader(archive))
	if err != nil {
		return "", fmt.Errorf("open source archive: %w", err)
	}
	defer zr.Close()
	tr := tar.NewReader(io.LimitReader(zr, 128<<20))
	for {
		header, err := tr.Next()
		if err == io.EOF {
			return "", fmt.Errorf("source archive has no root go.mod")
		}
		if err != nil {
			return "", fmt.Errorf("read source archive: %w", err)
		}
		if header.Name != "go.mod" {
			continue
		}
		if header.Typeflag != tar.TypeReg || header.Size <= 0 || header.Size > 1<<20 {
			return "", fmt.Errorf("source archive has an invalid go.mod")
		}
		data, err := io.ReadAll(tr)
		if err != nil {
			return "", fmt.Errorf("read source go.mod: %w", err)
		}
		return moduleGoVersion(data)
	}
}

func moduleGoVersion(data []byte) (string, error) {
	for _, line := range strings.Split(string(data), "\n") {
		fields := strings.Fields(strings.SplitN(line, "//", 2)[0])
		if len(fields) == 2 && fields[0] == "go" && goVersionPattern.MatchString(fields[1]) {
			return fields[1], nil
		}
	}
	return "", fmt.Errorf("source go.mod has no valid Go version directive")
}
